package co.edu.corhuila.property.payment.domain.model;

import java.util.UUID;

/** Identifier of the Reembolso aggregate. Generated by the domain on creation. */
public record ReembolsoId(UUID value) {

    public ReembolsoId {
        if (value == null) {
            throw new DomainException("El id del reembolso es requerido");
        }
    }

    public static ReembolsoId nueva() {
        return new ReembolsoId(UUID.randomUUID());
    }
}
